30	const LOCK_PATH = path.join(CLAUDE_DIR, '.backups', 'backup.lock');
31	const LOG_PATH = path.join(CLAUDE_DIR, '.backups', 'backup.log');
32	const LOCK_STALE_MS = 5 * 60 * 1000; // 5 min — any lock older is abandoned
