62	// Token encryption — derived from a stable machine-local key
63	function getMachineKey() {
64	  // Uses hostname + home dir as a weak-but-stable key derivation
65	  // For production: store a real secret in env var or OS keychain
66	  const seed = `${os.hostname()}-${os.homedir()}-claude-hub-backup-v1`;
67	  return crypto.createHash('sha256').update(seed).digest();
68	}
69	
70	function encryptToken(plaintext) {
71	  if (!plaintext) return '';
72	  const key = getMachineKey();
73	  const iv = crypto.randomBytes(12);
74	  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
75	  const enc = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
76	  const tag = cipher.getAuthTag();
77	  return `${iv.toString('base64')}:${tag.toString('base64')}:${enc.toString('base64')}`;
78	}
79	
80	function decryptToken(ciphertext) {
81	  if (!ciphertext) return '';
82	  try {
83	    const [ivB64, tagB64, encB64] = ciphertext.split(':');
84	    const key = getMachineKey();
85	    const iv = Buffer.from(ivB64, 'base64');
86	    const tag = Buffer.from(tagB64, 'base64');
87	    const enc = Buffer.from(encB64, 'base64');
88	    const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
89	    decipher.setAuthTag(tag);
90	    return Buffer.concat([decipher.update(enc), decipher.final()]).toString('utf8');
91	  } catch {
92	    return '';
93	  }
94	}
