96	function ensureDir(dir) {
97	  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
98	}
99	
100	// ──────────────────────────────────────────────────────────────────────────
101	//  Structured logging — rotated at 1 MB
102	// ──────────────────────────────────────────────────────────────────────────
103	
104	const LOG_MAX_BYTES = 1024 * 1024;
105	
106	function log(level, event, meta = {}) {
107	  try {
108	    ensureDir(path.dirname(LOG_PATH));
109	    if (fs.existsSync(LOG_PATH) && fs.statSync(LOG_PATH).size > LOG_MAX_BYTES) {
110	      fs.renameSync(LOG_PATH, LOG_PATH + '.1');
111	    }
112	    const line = JSON.stringify({
113	      t: new Date().toISOString(),
114	      level,
115	      event,
116	      ...meta,
117	    }) + '\n';
118	    fs.appendFileSync(LOG_PATH, line);
119	  } catch {
120	    // logging must never throw
121	  }
122	}
123	
124	function tailLog(lines = 200) {
125	  try {
126	    if (!fs.existsSync(LOG_PATH)) return [];
127	    const content = fs.readFileSync(LOG_PATH, 'utf-8');
128	    const all = content.trim().split('\n').filter(Boolean);
129	    return all.slice(-lines).map((l) => {
130	      try { return JSON.parse(l); } catch { return { t: '', level: 'raw', event: l }; }
131	    });
132	  } catch {
133	    return [];
134	  }
135	}
136	
137	// ──────────────────────────────────────────────────────────────────────────
138	//  Concurrency lock — prevents overlapping backups across restarts
139	// ──────────────────────────────────────────────────────────────────────────
140	
141	function acquireLock() {
142	  ensureDir(path.dirname(LOCK_PATH));
143	  if (fs.existsSync(LOCK_PATH)) {
144	    try {
145	      const stat = fs.statSync(LOCK_PATH);
146	      if (Date.now() - stat.mtimeMs < LOCK_STALE_MS) {
147	        return false; // active lock
148	      }
149	      // stale — reclaim
150	      log('warn', 'stale_lock_reclaimed', { ageMs: Date.now() - stat.mtimeMs });
151	    } catch {}
152	  }
153	  try {
154	    fs.writeFileSync(LOCK_PATH, String(process.pid), { flag: 'w' });
155	    return true;
156	  } catch {
157	    return false;
158	  }
159	}
160	
161	function releaseLock() {
162	  try {
163	    if (fs.existsSync(LOCK_PATH)) fs.unlinkSync(LOCK_PATH);
164	  } catch {}
165	}
