167	// ──────────────────────────────────────────────────────────────────────────
168	//  Push error classifier — turns raw git stderr into actionable diagnostics
169	// ──────────────────────────────────────────────────────────────────────────
170	
171	/**
172	 * Classify a git push / clone / auth failure into a stable error code.
173	 * Codes: REPO_NOT_FOUND | AUTH_INVALID | PERMISSION_DENIED | NETWORK |
174	 *        NON_FAST_FORWARD | LFS_REQUIRED | UNKNOWN
175	 */
176	function classifyGitError(rawMessage) {
177	  const msg = (rawMessage || '').toLowerCase();
178	
179	  if (/\b404\b|repository not found|not found\.?\s*$/.test(msg)) {
180	    return {
181	      code: 'REPO_NOT_FOUND',
182	      title: 'Repository does not exist',
183	      detail: 'The backup repo URL points to a repository that has not been created yet.',
184	      fix: 'Create the repo on GitHub, or click "Create Repo" to have us create it for you.',
185	      actions: ['create_remote', 'change_repo'],
186	    };
187	  }
188	  if (/\b401\b|bad credentials|authentication failed|could not read username/.test(msg)) {
189	    return {
190	      code: 'AUTH_INVALID',
191	      title: 'GitHub token is invalid or expired',
192	      detail: 'The stored Personal Access Token was rejected by GitHub.',
193	      fix: 'Generate a new fine-grained PAT with "Contents: Read and Write" scope and reconnect.',
194	      actions: ['reconnect'],
195	    };
196	  }
197	  if (/\b403\b|permission denied|forbidden|write access.*not granted|requested url returned error: 403/.test(msg)) {
198	    return {
199	      code: 'PERMISSION_DENIED',
200	      title: 'Token lacks write permission',
201	      detail: 'The token is valid but does not have write access to this repository.',
202	      fix: 'Regenerate the PAT with "Contents: Read and Write" scope for this repo, then reconnect.',
203	      actions: ['reconnect', 'verify_remote'],
204	    };
205	  }
206	  if (/non-fast-forward|fetch first|rejected.*fetch|updates were rejected/.test(msg)) {
207	    return {
208	      code: 'NON_FAST_FORWARD',
209	      title: 'Remote has diverged',
210	      detail: 'The remote branch has commits that are not in your local backup.',
211	      fix: 'Resolve manually — this usually means the remote was edited outside the backup system.',
212	      actions: ['retry_push'],
213	    };
214	  }
215	  if (/lfs|large file/.test(msg)) {
216	    return {
217	      code: 'LFS_REQUIRED',
218	      title: 'Large file detected',
219	      detail: 'A file exceeds GitHub\'s 100 MB limit and requires Git LFS.',
220	      fix: 'Exclude large files or enable Git LFS on the backup repo.',
221	      actions: [],
222	    };
223	  }
224	  if (/could not resolve host|network|timeout|getaddrinfo|econnrefused|econnreset/.test(msg)) {
225	    return {
226	      code: 'NETWORK',
227	      title: 'Network unreachable',
228	      detail: 'Could not reach GitHub. Your commits are safe locally and will push when connectivity returns.',
229	      fix: 'Check your internet connection, then retry.',
230	      actions: ['retry_push'],
231	    };
232	  }
233	  return {
234	    code: 'UNKNOWN',
235	    title: 'Push failed',
236	    detail: rawMessage ? rawMessage.split('\n')[0].slice(0, 200) : 'Unknown error',
237	    fix: 'Review the error detail and check the backup logs.',
238	    actions: ['retry_push', 'verify_remote'],
239	  };
240	}
