242	// ──────────────────────────────────────────────────────────────────────────
243	//  GitHub REST API — verify token, check repo existence, create repo
244	// ──────────────────────────────────────────────────────────────────────────
245	
246	function parseRepoUrl(repoUrl) {
247	  try {
248	    const url = new URL(repoUrl);
249	    if (url.hostname !== 'github.com') return null;
250	    const parts = url.pathname.replace(/^\/+/, '').replace(/\.git$/, '').split('/');
251	    if (parts.length < 2) return null;
252	    return { owner: parts[0], name: parts[1] };
253	  } catch {
254	    return null;
255	  }
256	}
257	
258	function githubRequest({ method, pathname, token, body }) {
259	  return new Promise((resolve) => {
260	    const data = body ? JSON.stringify(body) : null;
261	    const req = https.request({
262	      hostname: 'api.github.com',
263	      path: pathname,
264	      method,
265	      headers: {
266	        'Authorization': `Bearer ${token}`,
267	        'Accept': 'application/vnd.github+json',
268	        'X-GitHub-Api-Version': '2022-11-28',
269	        'User-Agent': 'Polyglot-Backup/1.0',
270	        ...(data ? { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } : {}),
271	      },
272	      timeout: 10000,
273	    }, (res) => {
274	      let chunks = '';
275	      res.on('data', (c) => chunks += c);
276	      res.on('end', () => {
277	        let parsed = null;
278	        try { parsed = chunks ? JSON.parse(chunks) : null; } catch {}
279	        resolve({ status: res.statusCode || 0, body: parsed, headers: res.headers });
280	      });
281	    });
282	    req.on('error', (err) => resolve({ status: 0, body: null, error: err.message }));
283	    req.on('timeout', () => { req.destroy(); resolve({ status: 0, body: null, error: 'timeout' }); });
284	    if (data) req.write(data);
285	    req.end();
286	  });
287	}
