289	async function verifyRemote() {
290	  const cfg = getBackupConfig();
291	  if (!cfg || !cfg.repoUrl) {
292	    return { ok: false, code: 'NOT_CONFIGURED', detail: 'No backup configured' };
293	  }
294	  const token = decryptToken(cfg.tokenEnc || '');
295	  if (!token) {
296	    return { ok: false, code: 'NO_TOKEN', detail: 'Token missing or undecryptable' };
297	  }
298	  const parsed = parseRepoUrl(cfg.repoUrl);
299	  if (!parsed) {
300	    return { ok: false, code: 'BAD_URL', detail: 'Repo URL must be https://github.com/OWNER/NAME(.git)' };
301	  }
302	
303	  // 1. Token identity — /user
304	  const whoami = await githubRequest({ method: 'GET', pathname: '/user', token });
305	  if (whoami.status === 401) {
306	    return { ok: false, code: 'AUTH_INVALID', detail: 'Token rejected by GitHub', repo: parsed };
307	  }
308	  if (whoami.status !== 200) {
309	    return { ok: false, code: 'NETWORK', detail: whoami.error || `GitHub API ${whoami.status}`, repo: parsed };
310	  }
311	  const user = whoami.body?.login;
312	
313	  // 2. Token scopes — classic PATs expose them via header; fine-grained return null
314	  const scopes = (whoami.headers?.['x-oauth-scopes'] || '').split(',').map((s) => s.trim()).filter(Boolean);
315	
316	  // 3. Repo existence — /repos/:owner/:name
317	  const repo = await githubRequest({
318	    method: 'GET',
319	    pathname: `/repos/${parsed.owner}/${parsed.name}`,
320	    token,
321	  });
322	
323	  if (repo.status === 404) {
324	    return {
325	      ok: false,
326	      code: 'REPO_NOT_FOUND',
327	      detail: `Repository ${parsed.owner}/${parsed.name} does not exist (or token can't see it)`,
328	      repo: parsed,
329	      user,
330	      scopes,
331	      canCreate: parsed.owner === user || scopes.includes('repo'),
332	    };
333	  }
334	  if (repo.status === 403) {
335	    return { ok: false, code: 'PERMISSION_DENIED', detail: 'Token lacks access to this repo', repo: parsed, user, scopes };
336	  }
337	  if (repo.status !== 200) {
338	    return { ok: false, code: 'NETWORK', detail: repo.error || `GitHub API ${repo.status}`, repo: parsed };
339	  }
340	
341	  // 4. Write permission
342	  const canWrite = !!repo.body?.permissions?.push;
343	  if (!canWrite) {
344	    return {
345	      ok: false,
346	      code: 'PERMISSION_DENIED',
347	      detail: 'Token has read access but not write access',
348	      repo: parsed,
349	      user,
350	      scopes,
351	    };
352	  }
353	
354	  return {
355	    ok: true,
356	    code: 'OK',
357	    detail: 'Token valid, repo exists, write access confirmed',
358	    repo: parsed,
359	    user,
360	    scopes,
361	    isPrivate: !!repo.body?.private,
362	    defaultBranch: repo.body?.default_branch || 'main',
363	  };
364	}
