366	async function createRemote({ private: isPrivate = true } = {}) {
367	  const cfg = getBackupConfig();
368	  if (!cfg || !cfg.repoUrl) return { ok: false, error: 'No backup configured' };
369	  const token = decryptToken(cfg.tokenEnc || '');
370	  if (!token) return { ok: false, error: 'Token missing' };
371	  const parsed = parseRepoUrl(cfg.repoUrl);
372	  if (!parsed) return { ok: false, error: 'Invalid repo URL' };
373	
