384	  const result = await githubRequest({
385	    method: 'POST',
386	    pathname: createPath,
387	    token,
388	    body: {
389	      name: parsed.name,
390	      private: isPrivate,
391	      description: 'Polyglot — encrypted backup of ~/.claude/',
392	      auto_init: false,
