546	// Granular category labels — memory split by subdirectory so curriculum,
547	// patterns, stacks etc. appear as distinct bullet points in the commit body.
548	function categoryFor(relPath) {
549	  const p = relPath.replace(/\\/g, '/');
550	  if (p === 'CLAUDE.md') return 'CLAUDE.md';
551	  if (p === 'settings.json') return 'settings';
552	  if (p.startsWith('agents/')) return 'agents';
553	  if (p.startsWith('memory/')) {
554	    const sub = p.slice(7).split('/')[0]; // first segment after memory/
555	    const known = ['curriculum', 'patterns', 'stacks', 'design', 'content',
556	                   'skills', 'user', 'projects', 'training'];
557	    return known.includes(sub) ? `memory/${sub}` : 'memory';
558	  }
559	  if (p.startsWith('rules/')) return 'rules';
560	  if (p.startsWith('commands/')) return 'commands';
561	  if (p.startsWith('templates/')) return 'templates';
562	  if (p.startsWith('projects/')) return 'projects';
563	  if (p.startsWith('history/')) return 'history';
564	  if (p.startsWith('logs/')) return 'logs';
565	  return 'other';
566	}
