568	// Short human-readable label for a single file — used in the body bullet list.
569	// Strips hashes, long path prefixes, and known extensions so only the
570	// meaningful name remains.
571	function shortName(relPath) {
572	  const p = relPath.replace(/\\/g, '/');
573	  const base = path.basename(p).replace(/\.(md|json|yaml|yml|txt)$/, '');
574	
575	  if (p === 'CLAUDE.md' || p === 'settings.json') return base;
576	  if (p.startsWith('agents/')) return base;
577	  if (p.startsWith('memory/') || p.startsWith('rules/') ||
578	      p.startsWith('commands/') || p.startsWith('templates/')) return base;
579	
580	  if (p.startsWith('projects/')) {
581	    const parts = p.split('/');
582	    const dirName = parts[1] || '';
583	    // dir is encoded fs path: -Users-yashbaldha-Desktop-Boldteq-App-<Name>
584	    const skipWords = new Set(['users', 'yashbaldha', 'desktop', 'boldteq',
585	                               'app', 'home', 'code', 'repos']);
586	    const words = dirName.split('-').filter(w => w && !skipWords.has(w.toLowerCase()));
587	    const projectName = words.slice(0, 3).join('-') || dirName.slice(-15);
588	    const filename = parts[2] || '';
589	    if (!filename) return projectName;
590	    if (filename.endsWith('.jsonl')) return `${projectName} history`;
591	    if (filename === 'CLAUDE.md') return `${projectName} CLAUDE.md`;
592	    if (filename === 'agents' && parts[3]) {
593	      return `${projectName} agent/${parts[3].replace(/\.md$/, '')}`;
594	    }
595	    return `${projectName}/${path.basename(filename)}`;
596	  }
597	
598	  return base;
599	}
