601	// Friendly name for the single-file commit title.
602	function friendlyName(relPath) {
603	  const p = relPath.replace(/\\/g, '/');
604	  if (p.startsWith('agents/')) return `agent ${path.basename(p, '.md')}`;
605	  if (p.startsWith('rules/')) return `rule ${path.basename(p, '.md')}`;
606	  if (p.startsWith('commands/')) return `command ${path.basename(p, '.md')}`;
607	  if (p.startsWith('templates/')) return `template ${path.basename(p, '.md')}`;
608	  return shortName(relPath);
