611	// Build the ≤72-char title in conventional-commits style:
612	//   chore: agents(3), memory/curriculum(1), projects(4)
613	function buildTitle(all, categories) {
614	  if (all.length === 1) {
615	    const item = all[0];
616	    const verb = item.op === '+' ? 'add' : item.op === '-' ? 'remove' : 'update';
617	    return `chore: ${verb} ${friendlyName(item.path)}`.slice(0, 72);
618	  }
619	
620	  const ranked = Object.entries(categories)
621	    .map(([name, files]) => ({ name, count: files.length }))
622	    .sort((a, b) => b.count - a.count);
623	
624	  // Build "cat(n), cat(n), ..." fitting within 72 chars
625	  const prefix = 'chore: ';
626	  const budget = 72 - prefix.length;
627	  const parts = [];
628	  let used = 0;
629	  for (const { name, count } of ranked) {
630	    const token = `${name}(${count})`;
631	    const extra = parts.length === 0 ? token.length : token.length + 2; // ", "
632	    if (used + extra > budget) {
633	      const rem = ranked.length - parts.length;
634	      if (rem > 0) parts.push(`+${rem} more`);
635	      break;
636	    }
637	    parts.push(token);
638	    used += extra;
639	  }
640	  return `${prefix}${parts.join(', ')}`.slice(0, 72);
641	}
