643	// Build the body as one bullet per category:
644	//   - agents (3): decoder, spark (~), elio (new)
645	//   - projects (4): Marketing-Site history (×2), Polyglot history, Ecom-testing history
646	function buildBody(categories) {
647	  const MAX_PER_BULLET = 6;
648	  const opRank = { '~': 0, '+': 1, '-': 2 };
649	  const ordered = Object.entries(categories).sort((a, b) => b[1].length - a[1].length);
650	  const lines = [];
651	
652	  for (const [cat, files] of ordered) {
653	    const sorted = [...files].sort((a, b) => opRank[a.op] - opRank[b.op]);
654	
655	    // Build short label for each file, annotate op only when it adds signal
656	    const hasAdd = sorted.some(f => f.op === '+');
657	    const hasDel = sorted.some(f => f.op === '-');
658	    const mixedOps = hasAdd || hasDel;
659	
660	    const rawNames = sorted.map(f => {
661	      const sn = shortName(f.path);
662	      const tag = mixedOps ? (f.op === '+' ? ' (new)' : f.op === '-' ? ' (del)' : '') : '';
663	      return `${sn}${tag}`;
664	    });
665	
666	    // Deduplicate with ×N suffix (common for project history JSONL)
667	    const counts = {};
668	    for (const n of rawNames) counts[n] = (counts[n] || 0) + 1;
669	    const deduped = [];
670	    const seen = new Set();
671	    for (const n of rawNames) {
672	      if (seen.has(n)) continue;
673	      seen.add(n);
674	      deduped.push(counts[n] > 1 ? `${n} (×${counts[n]})` : n);
675	    }
676	
677	    const shown = deduped.slice(0, MAX_PER_BULLET);
678	    const extra = deduped.length - shown.length;
679	    const nameList = shown.join(', ') + (extra > 0 ? `, +${extra} more` : '');
680	    lines.push(`- ${cat} (${files.length}): ${nameList}`);
681	  }
682	
683	  return lines.join('\n');
684	}
