686	// Generate a descriptive commit message from the git status
687	async function generateCommitMessage(git) {
688	  const status = await git.status();
689	  const all = [
690	    ...status.modified.map(f => ({ path: f, op: '~' })),
691	    ...status.not_added.map(f => ({ path: f, op: '+' })),
692	    ...status.created.map(f => ({ path: f, op: '+' })),
693	    ...status.deleted.map(f => ({ path: f, op: '-' })),
694	  ];
695	  if (all.length === 0) return null;
696	
697	  // Categorize every file
698	  const categories = {};
699	  for (const item of all) {
700	    const cat = categoryFor(item.path);
701	    if (!categories[cat]) categories[cat] = [];
702	    categories[cat].push(item);
703	  }
704	
705	  const title = buildTitle(all, categories);
706	  if (all.length === 1) return title;
707	  return `${title}\n\n${buildBody(categories)}`;
708	}
