883	/**
884	 * Push with automatic rebase on non-fast-forward errors.
885	 * Strategy:
886	 *   1. Normal push
887	 *   2. If NON_FAST_FORWARD → git pull --rebase origin main → retry push
888	 *   3. If rebase fails (conflict) → abort rebase, push --force-with-lease
889	 *      (safer than --force: fails if remote changed since our last fetch)
890	 * Returns { ok: true } or throws the original push error.
891	 */
892	async function pushWithAutoRebase(git) {
893	  try {
894	    await git.push(['-u', 'origin', 'main']);
895	    return { ok: true, strategy: 'direct' };
896	  } catch (pushErr) {
897	    const diagnosis = classifyGitError(pushErr.message);
898	    if (diagnosis.code !== 'NON_FAST_FORWARD') throw pushErr;
899	
900	    log('info', 'push_non_ff_detected_rebasing');
901	    try {
902	      await git.fetch(['origin', 'main']);
903	      await git.pull(['--rebase', 'origin', 'main']);
904	      await git.push(['-u', 'origin', 'main']);
905	      log('info', 'push_after_rebase_ok');
906	      return { ok: true, strategy: 'rebase' };
907	    } catch (rebaseErr) {
908	      log('warn', 'rebase_failed_fallback_to_force_with_lease', { err: rebaseErr.message });
909	      try { await git.raw(['rebase', '--abort']); } catch {}
910	      await git.push(['--force-with-lease', '-u', 'origin', 'main']);
911	      log('info', 'push_force_with_lease_ok');
912	      return { ok: true, strategy: 'force-with-lease' };
913	    }
914	  }
915	}
