1146	function createSnapshot(targetPath, agentName = 'unknown') {
1147	  try {
1148	    if (!fs.existsSync(targetPath)) return null;
1149	    ensureDir(SNAPSHOTS_DIR);
1150	
1151	    const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
1152	    const rel = path.relative(CLAUDE_DIR, targetPath).replace(/[/\\]/g, '__');
1153	    const snapName = `${ts}__${agentName}__${rel}`;
1154	    const snapPath = path.join(SNAPSHOTS_DIR, snapName);
1155	
1156	    fs.copyFileSync(targetPath, snapPath);
1157	    rotateSnapshots();
1158	    return snapPath;
1159	  } catch (err) {
1160	    console.warn('Snapshot failed:', err.message);
1161	    return null;
1162	  }
1163	}
