1165	function rotateSnapshots() {
1166	  try {
1167	    if (!fs.existsSync(SNAPSHOTS_DIR)) return;
1168	    const entries = fs.readdirSync(SNAPSHOTS_DIR)
1169	      .map((name) => ({
1170	        name,
1171	        mtime: fs.statSync(path.join(SNAPSHOTS_DIR, name)).mtime.getTime(),
1172	      }))
1173	      .sort((a, b) => b.mtime - a.mtime); // newest first
1174	
1175	    if (entries.length <= MAX_SNAPSHOTS) return;
1176	
1177	    for (const old of entries.slice(MAX_SNAPSHOTS)) {
1178	      fs.unlinkSync(path.join(SNAPSHOTS_DIR, old.name));
1179	    }
1180	  } catch {}
1181	}
