1187	      .map((name) => {
1188	        const full = path.join(SNAPSHOTS_DIR, name);
1189	        const stat = fs.statSync(full);
1190	        // Format: TS__agent__rel-path
1191	        const parts = name.split('__');
1192	        const ts = parts[0];
1193	        const agent = parts[1];
1194	        const rel = parts.slice(2).join('__').replace(/__/g, '/');
1195	        return {
1196	          name,
1197	          ts,
1198	          agent,
1199	          relPath: rel,
1200	          size: stat.size,
1201	          mtime: stat.mtime.toISOString(),
1202	        };
1203	      })
1204	      .sort((a, b) => b.mtime.localeCompare(a.mtime));
1205	  } catch {
1206	    return [];
1207	  }
1208	}
