1231	// Count files in INCLUDE_PATHS modified after a given timestamp.
1232	// Cheap directory walk + mtime check; capped to avoid runaway scans on huge trees.
1233	function countChangedSince(sinceISO) {
1234	  if (!sinceISO) {
1235	    // No prior backup → don't claim changes; treat as 'unknown' upstream.
1236	    return { count: null, sample: [], scanLimited: false };
1237	  }
1238	  const since = new Date(sinceISO).getTime();
1239	  if (Number.isNaN(since)) return { count: null, sample: [], scanLimited: false };
1240	
1241	  const SCAN_FILE_CAP = 20000;        // hard ceiling on files inspected
1242	  const SAMPLE_CAP = 5;               // surface a few example paths in UI
1243	  let count = 0;
1244	  let scanned = 0;
1245	  let scanLimited = false;
1246	  const sample = [];
1247	
1248	  const skipNames = new Set(['.git', 'node_modules', '.DS_Store', 'caches', '.backups']);
1249	
1250	  function walk(absPath, relRoot) {
1251	    if (scanLimited) return;
1252	    let entries;
1253	    try { entries = fs.readdirSync(absPath, { withFileTypes: true }); } catch { return; }
1254	    for (const ent of entries) {
1255	      if (scanLimited) return;
1256	      if (skipNames.has(ent.name)) continue;
1257	      const full = path.join(absPath, ent.name);
1258	      const rel = path.join(relRoot, ent.name);
1259	      if (ent.isDirectory()) {
1260	        walk(full, rel);
1261	      } else if (ent.isFile()) {
1262	        scanned++;
1263	        if (scanned > SCAN_FILE_CAP) { scanLimited = true; return; }
1264	        let stat;
1265	        try { stat = fs.statSync(full); } catch { continue; }
1266	        if (stat.mtimeMs > since) {
1267	          count++;
1268	          if (sample.length < SAMPLE_CAP) sample.push(rel);
1269	        }
1270	      }
1271	    }
1272	  }
1273	
1274	  for (const rel of INCLUDE_PATHS) {
1275	    if (scanLimited) break;
1276	    const abs = path.join(CLAUDE_DIR, rel);
1277	    if (!fs.existsSync(abs)) continue;
1278	    let stat;
1279	    try { stat = fs.statSync(abs); } catch { continue; }
1280	    if (stat.isDirectory()) {
1281	      walk(abs, rel);
1282	    } else if (stat.isFile()) {
1283	      scanned++;
1284	      if (stat.mtimeMs > since) {
1285	        count++;
1286	        if (sample.length < SAMPLE_CAP) sample.push(rel);
1287	      }
1288	    }
1289	  }
1290	
1291	  return { count, sample, scanLimited };
1292	}
